  $('#rf-mode-t').textContent = FORM.mode === 'tunggal' ? 'Satu item atau rute. Harga baru untuk rute yang sama otomatis menjadi versi baru.' : 'Satu quotation berisi beberapa komponen lintas lini, satuan per project. Margin dinilai di total paket.';
  FORM.liniTunggal = '__baru__'; FORM.petaTunggal = new Map();
