  FORM.cid = cid; FORM.edit = ed; FORM.mode = ed ? (ed.komponen ? 'paket' : 'tunggal') : (opsi.mode || 'tunggal');
  FORM.nama = src && src.komponen ? src.nama + (sal ? ' (salinan)' : '') : '';
  FORM.komp = src && src.komponen ? src.komponen.map(k => ({ id: uid('k'), lini: namaLini(k.lini, k.liniNama), item: k.item, satuan: k.satuan, jual: k.jual ?? '', modal: k.modal ?? '', vendor: vendorTampil(k), tarif: '', tk: ed ? (k.tarifKunci || '') : '', om: ed && k.modalDariMR ? String(k.modal) : '', dm: ed && k.modalDariMR ? '1' : '' })) : [kompKosong(), kompKosong()];
