const angkaDok = n => Number(n).toLocaleString('id-ID', { maximumFractionDigits: 2 });
const angkaF = n => Number(n).toLocaleString('id-ID', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const SATU = ['', 'satu', 'dua', 'tiga', 'empat', 'lima', 'enam', 'tujuh', 'delapan', 'sembilan', 'sepuluh', 'sebelas'];
function tbID(n) {
  n = Math.floor(n);
  if (n < 12) return SATU[n]; if (n < 20) return tbID(n - 10) + ' belas';
  if (n < 100) return tbID(Math.floor(n / 10)) + ' puluh' + (n % 10 ? ' ' + tbID(n % 10) : '');
  if (n < 200) return 'seratus' + (n - 100 ? ' ' + tbID(n - 100) : '');
  if (n < 1000) return tbID(Math.floor(n / 100)) + ' ratus' + (n % 100 ? ' ' + tbID(n % 100) : '');
  if (n < 2000) return 'seribu' + (n - 1000 ? ' ' + tbID(n - 1000) : '');
  const sk = [[1e12, 'triliun'], [1e9, 'miliar'], [1e6, 'juta'], [1e3, 'ribu']];
  for (const [v, nm] of sk) if (n >= v) return tbID(Math.floor(n / v)) + ' ' + nm + (n % v ? ' ' + tbID(n % v) : '');
  return '';
}
const UNIT_EN = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
const TENS_EN = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
function tbEN(n) {
  n = Math.floor(n);
  if (n < 20) return UNIT_EN[n]; if (n < 100) return TENS_EN[Math.floor(n / 10)] + (n % 10 ? '-' + UNIT_EN[n % 10] : '');
  if (n < 1000) return UNIT_EN[Math.floor(n / 100)] + ' hundred' + (n % 100 ? ' ' + tbEN(n % 100) : '');
  const sk = [[1e12, 'trillion'], [1e9, 'billion'], [1e6, 'million'], [1e3, 'thousand']];
  for (const [v, nm] of sk) if (n >= v) return tbEN(Math.floor(n / v)) + ' ' + nm + (n % v ? ' ' + tbEN(n % v) : '');
  return '';
}
const kapital = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
R.terbilang = (n, b) => { n = Math.round(Number(n) || 0); if (n === 0) return b === 'en' ? 'Zero rupiah.' : 'Nol rupiah.'; return kapital(b === 'en' ? tbEN(n) : tbID(n)) + ' rupiah.'; };

