  if (bawaan) delete baru[TB.lini]; else baru[TB.lini] = { mode: TB.mode, pivot: TB.pivot, labelBaris: TB.labelBaris, nomor: TB.nomor, note: TB.note, bag: TB.bag, fmtUkuran: TB.ft, awalan: { ...TB.aw }, judulBaris: { ...TB.jb }, judulTarif: { ...TB.jt }, judulNote: { ...TB.jn }, kolom: TB.kolom.map(k => ({ src: k.src, id: String(k.id || '').trim(), en: String(k.en || '').trim() })) };
