const taruh = q => { const i = DB.list.findIndex(x => x.id === q.id); const c = clone(q); if (i >= 0) DB.list[i] = c; else DB.list.push(c); };
const catat = (q, dari, ke, catatan) => { q.log = q.log || []; q.log.push({ waktu: stempel(), oleh: OLEH(), dari, ke, catatan: catatan || '' }); };
