function cariCustomer(q) {
  let c = q.customerId ? cust(q.customerId) : null;
  if (!c) { const d = npwpKunci(q.npwp); if (d.length >= 15) c = S.customers.find(x => npwpKunci(x.npwp) === d) || null; }
  if (!c) { const k = namaKunci(q.customerNama); if (k) c = S.customers.find(x => namaKunci(x.nama) === k || (x.alias && namaKunci(x.alias) === k)) || null; }
  return c;
}
/* nama yang mirip tetapi tidak sama persis: ditampilkan sebagai saran, tidak otomatis dihubungkan */
