    q.tindakLanjut = q.tindakLanjut || []; q.tindakLanjut.push({ tanggal, catatan, oleh: OLEH(), waktu: stempel() }); catat(q, 'terkirim', 'terkirim', 'Tindak lanjut: ' + catatan); q.diubahPada = stempel();
