/* penanda "perlu perhatian" dari pemilik quotation (tidak mengubah nomor atau isi dokumen) */
Repo.tandai = async function (id, nyala) {
  await tulis(() => {
    const q = DB.list.find(x => x.id === id); if (!q) throw new Error('Quotation tidak ditemukan.');
    q.perhatian = nyala ? { oleh: OLEH(), waktu: stempel() } : null; q.diubahPada = stempel();
  }, () => { const q = DB.list.find(x => x.id === id); return !!q && (nyala ? !!q.perhatian : !q.perhatian); });
};
async function tandaiPerhatian(id) {
  const q = Repo.baca(id); if (!q) return;
  try { await Repo.tandai(id, !q.perhatian); gambar(); toast(q.perhatian ? 'Tanda perhatian dihapus.' : 'Quotation ditandai perlu perhatian.'); }
  catch (err) { toast(err.message, 'bahaya'); }
}
Repo.tidakDipakai = async function (id, alasan, tanggal) {
  await tulis(() => {
    const q = DB.list.find(x => x.id === id); if (!q || !R.bolehTransisi(q.status, 'tidak_dipakai')) throw new Error('Quotation tidak bisa ditandai tidak dipakai dari status ini.');
    q.status = 'tidak_dipakai'; q.alasanTidakDipakai = alasan; q.diputuskan = tanggal; catat(q, 'terkirim', 'tidak_dipakai', alasan); q.diubahPada = stempel();
  }, () => { const x = DB.list.find(z => z.id === id); return !!x && x.status === 'tidak_dipakai' && x.alasanTidakDipakai === alasan; });
};
/* Pengaturan pribadi (admin dan sales): salinan kop, penandatangan, kalimat, tabel, dan syarat untuk quotation buatan akun ini.
   Pengaturan global tetap milik master. Butir syarat yang ditandai wajib selalu diambil dari master dan tidak bisa dimatikan. */
const PENG_PRIBADI = ['kop', 'penandatangan', 'pembuka', 'penutup', 'catatan', 'kalimatLini', 'syaratLini', 'tabelLini', 'tabelUniversal', 'tnc', 'pengingat'];
/* Pengaturan pribadi hanya menyimpan bagian yang diubah (selisih terhadap global), jadi perubahan master di bagian lain tetap berlaku.
   Nilai null menandai bagian yang dihapus pribadi. Daftar (array) disimpan utuh bila berbeda. */
const selisihPeng = (a, g) => {
  if (a && typeof a === 'object' && !Array.isArray(a) && g && typeof g === 'object' && !Array.isArray(g)) {
    const o = {};
    new Set([...Object.keys(a), ...Object.keys(g)]).forEach(k => {
      if (!(k in a)) { if (k in g) o[k] = null; return; }
      const d = selisihPeng(a[k], g[k]); if (d !== undefined) o[k] = d;
    });
    return Object.keys(o).length ? o : undefined;
  }
  return JSON.stringify(a) === JSON.stringify(g) ? undefined : clone(a);
};
const terapkanSelisih = (dasar, sel) => {
  if (sel === undefined) return dasar;
  if (sel === null) return undefined;
  if (Array.isArray(sel) || typeof sel !== 'object') return clone(sel);
  const o = dasar && typeof dasar === 'object' && !Array.isArray(dasar) ? { ...clone(dasar) } : {};
  Object.keys(sel).forEach(k => { const v = terapkanSelisih(o[k], sel[k]); if (v === undefined) delete o[k]; else o[k] = v; });
  return o;
};
/* dasar pengaturan untuk admin dan sales: global, dengan penandatangan dari nama profil bila belum diatur */
function dasarPribadi(g) {
  const d = clone(g);
  d.penandatangan = { nama: (window.__ISL && window.__ISL.nama) || g.penandatangan.nama, jabatan: clone(g.penandatangan.jabatan) };
  return d;
}
function terapkanPribadi() {
  const g = window.__islPengGlobal; if (!g || kelolaSaja()) return;
  const sel = (window.__ISL_PROFIL || {}).pengaturanPribadi || {};
  const dasar = dasarPribadi(g);
  const hasil = {};
  PENG_PRIBADI.forEach(k => { hasil[k] = terapkanSelisih(dasar[k], sel[k]); });
  Object.keys(PENG).forEach(k => { PENG[k] = clone(PENG_PRIBADI.includes(k) ? (hasil[k] !== undefined ? hasil[k] : g[k]) : g[k]); });
  const kunci = t => String((t.teks && t.teks.id) || '').trim();
  const wajib = (g.tnc || []).filter(t => t.wajib).map(t => ({ ...clone(t), aktif: true }));
  PENG.tnc = [...wajib, ...(PENG.tnc || []).filter(t => !t.wajib && !wajib.some(w => kunci(w) === kunci(t)))];
}
Repo.simpanPribadi = async function (baru) {
  const g = dasarPribadi(window.__islPengGlobal || baru), sel = {};
  PENG_PRIBADI.forEach(k => { const d = selisihPeng(baru[k], g[k]); if (d !== undefined) sel[k] = d; });
  await window.__islSimpanProfil({ pengaturanPribadi: sel });
  if (window.__ISL_PROFIL) window.__ISL_PROFIL.pengaturanPribadi = sel;
  terapkanPribadi();
};
Repo.simpanPengaturan = async function (baru) {
  if (!kelolaSaja()) return Repo.simpanPribadi(baru);
  const salin = clone(baru);
  /* "Nomor terakhir terpakai" yang diisi lebih besar dari hitungan berjalan menaikkan hitungan (penghitung hanya boleh naik; lihat aturan qt_counters) */
  const atur = {}, resetBaru = (salin.nomor || {}).reset || 'bulanan';
  ((salin.nomor && salin.nomor.seri) || []).forEach(x => {
    const k = Repo.kunciUrut(HARI_INI(), x.kode, resetBaru), a = Math.max(0, parseInt(x.awal, 10) || 0);
    /* beralih dari bulanan ke tahunan: hitungan tahun ini mulai dari urutan tertinggi bulan-bulan sebelumnya, supaya nomor tidak kembar */
    const dariBulan = (resetBaru === 'tahunan' && ((PENG.nomor || {}).reset || 'bulanan') !== 'tahunan') ? Math.max(0, ...Object.keys(DB.urutTahun).filter(z => z.startsWith(x.kode + '|' + HARI_INI().slice(0, 4) + '-')).map(z => DB.urutTahun[z] || 0)) : 0;
    const tinggi = Math.max(a, dariBulan); if (tinggi !== (DB.urutTahun[k] || 0)) atur[k] = tinggi;
    x.awal = 0; x.periode = null;
  });
  await tulis(() => { Object.keys(PENG).forEach(k => delete PENG[k]); Object.assign(PENG, clone(salin)); Object.entries(atur).forEach(([k, v]) => { DB.urutTahun[k] = v; }); },
    () => JSON.stringify(PENG) === JSON.stringify(salin) && Object.entries(atur).every(([k, v]) => DB.urutTahun[k] === v));
};

