function pasangCssDok() { if (!document.getElementById('isl-doc-css')) { const s = document.createElement('style'); s.id = 'isl-doc-css'; s.textContent = DOC_CSS; document.head.appendChild(s); } }
let fontSiap = false;
async function siapkanFont() {
  if (fontSiap || !document.fonts) return; fontSiap = true;
  try { await Promise.all(['600 12px ISLPJS', '700 12px ISLPJS', '800 12px ISLPJS', '400 12px ISLInt', '500 12px ISLInt', '600 12px ISLInt', '700 12px ISLInt', 'italic 300 12px ISLPop', 'italic 500 12px ISLPop'].map(f => document.fonts.load(f))); await document.fonts.ready; } catch { }
}
const htmlEl = h => { const d = document.createElement('div'); d.innerHTML = h.trim(); return d.firstElementChild; };
const htmlTr = h => { const t = document.createElement('tbody'); t.innerHTML = h.trim(); return t.firstElementChild; };

/* Pengaman tabel lanjutan: bila sebuah grup rowspan (mis. kolom No) terpotong di pergantian halaman, baris di halaman berikutnya kehilangan sel itu dan seluruh kolomnya bergeser.
   Sel kosong ditambahkan di depan baris yang kurang sel, dengan memperhitungkan rowspan yang masih berlaku di halaman yang sama. */
function perbaikiRowspan(tabel) {
  const ncol = tabel.querySelectorAll('colgroup col').length; if (!ncol) return;
  const sisa = new Array(ncol).fill(0);
  tabel.querySelectorAll('tbody > tr').forEach(tr => {
    const sel = [...tr.children], dipakai = sisa.filter(x => x > 0).length, punya = sel.reduce((a, td) => a + (td.colSpan || 1), 0);
    if (dipakai + punya < ncol) { for (let k = 0; k < ncol - dipakai - punya; k++) tr.insertBefore(Object.assign(document.createElement('td'), { className: 'c' }), tr.firstChild); }
    let col = 0;
    [...tr.children].forEach(td => { while (col < ncol && sisa[col] > 0) col++; const cs = td.colSpan || 1, rsn = td.rowSpan || 1; for (let k = 0; k < cs && col + k < ncol; k++) sisa[col + k] = rsn; col += cs; });
    for (let c = 0; c < ncol; c++) if (sisa[c] > 0) sisa[c]--;
  });
}

