  /* riwayat PDF (quotation di luar sistem) ikut tampil di daftar, dikelompokkan ke status quotation terdekat */
  const listRw = Q.fSumber === 'sistem' ? [] : SB.saring('riwayat', rw).filter(x => (!Q.fStatus || RW_KELOMPOK[x.status] === Q.fStatus) && (!Q.fTahun || rwPutus(x).startsWith(Q.fTahun)) && cariR(x));
  const kpiItem = !Q.kpi ? null : Q.kpi === 'draf' ? Repo.semua().filter(q => q.status === 'draf').map(x => ({ x, rw: false, kat: 'draf' })) : kpiTerbitBulanIni().item.filter(it => Q.kpi === 'terbit' || (Q.kpi === 'belum' ? ['menunggu', 'diabaikan', 'ditolak'].includes(it.kat) : it.kat === Q.kpi));
  const list = (kpiItem ? kpiItem.map(it => ({ x: it.x, rw: it.rw })) : [...listQ.map(x => ({ x })), ...listRw.map(x => ({ x, rw: true }))])
    .sort((a, b) => tglUrutList(b).localeCompare(tglUrutList(a)) || nomorUrutList(b) - nomorUrutList(a));
  const bannerKpi = kpiItem ? `<div class="mr-banner">${ik('info')}<div>Menampilkan quotation terbit bulan ini · <b>${{ terbit: 'semua hasil', belum: 'belum disetujui', draf: 'draf', disetujui: 'disetujui' }[Q.kpi]}</b> (${list.length}). Filter lain tidak ikut. <button type="button" class="qt-link" data-qt="kpi-reset">Tampilkan semua</button></div></div>` : '';
  const gagalRw = window.__islGagalBaca && window.__islGagalBaca.has('qt_riwayat') ? `<div class="mr-banner mr-banner--peringatan">${ik('peringatan')}<div><b>Riwayat PDF belum bisa dibaca.</b> Quotation yang diunggah lewat PDF tidak tampil sampai data dibaca. Cek koneksi dan aturan Firebase di Pengaturan dokumen, lalu muat ulang halaman.</div></div>` : '';
