function selBaris(b) {
  if (!R.adaModal(b) || !(Number(b.jual) > 0)) return '<span class="cu-kosong">—</span>';
  const m = mg(Number(b.jual), Number(b.modal)), tot = m.rp * (Number(b.qty) || 0), bm = b.jenis === 'rate' ? bench(m.pct, Number(b.modal), R.targetLive(b)) : { st: 'tanpa-target' };
  return `<b class="${m.rp < 0 ? 'cu-neg' : 'cu-pos'}">${rpS(Math.round(tot))}</b><small>${m.pct === null ? '' : fmtPct(m.pct)}${bm.st === 'tanpa-target' || bm.st === 'tanpa-modal' ? '' : ` · ${bm.st === 'bawah' ? '▼' : '▲'} ${fmtPoin(bm.poin)}`}</small>`;
}
