  const enBantu = (jenis, f) => { if (e.bahasa !== 'en') return ''; const st = R.kalimatEnStatus(e, jenis); const ket = { kamus: 'English otomatis dari kamus.', manual: 'Memakai English isian manual.', belum: 'Belum bisa diterjemahkan otomatis, saat cetak memakai template. Isi English manual di bawah bila perlu.' }[st]; return `<small class="cu-hint">${ket}</small><textarea id="${f}" rows="2" placeholder="English (opsional)">${esc(e[jenis === 'pembuka' ? 'pembukaEn' : 'penutupEn'] || '')}</textarea>`; };
