/* ---------- DOKUMEN: pratinjau, unduh, email, cetak ---------- */
async function panelDokumen(q) {
  const terbit = !!q.dokumenModel, c = cust(q.customerId);
  const m = terbit ? q.dokumenModel : R.bangunModel(q, c), aset = terbit ? Repo.aset(q.id) : asetSekarang();
  bukaPanel(`<header class="mr-panel__kepala"><div><h2>${terbit ? 'Dokumen penawaran' : 'Pratinjau dokumen'}</h2><p class="mr-sub"><span id="qt-dokinfo">Menyusun halaman…</span> · ${m.bahasa === 'en' ? 'English' : 'Indonesia'} · ${m.tipe === 'project' ? 'Harga total project' : 'Harga per layanan'}</p></div><button class="mr-btn mr-btn--kecil" data-aksi="tutup-layer">Tutup pratinjau</button><button class="mr-ikonbtn" data-aksi="tutup-layer" aria-label="Tutup">${ik('tutup')}</button></header>
  <div class="mr-panel__isi qt-dokpanel">${!terbit && R.kopBelumDiisi() ? `<div class="mr-banner mr-banner--peringatan">${ik('peringatan')}<div>Data kop, nama penandatangan, atau gambar tanda tangan dan cap masih contoh. Lengkapi di Pengaturan dokumen sebelum menerbitkan.</div></div>` : ''}${!terbit ? `<div class="mr-banner">${ik('info')}<div>Pratinjau berwatermark DRAF. Nomor resmi diberikan dan PDF dibuat saat <b>Terbitkan dan unduh PDF</b>.</div></div>` : ''}
    <div id="qt-dokwrap" class="qt-dokwrap"></div></div>
  <footer class="mr-panel__kaki"><button class="mr-btn" data-aksi="tutup-layer">Tutup</button>${terbit ? `<button class="mr-btn mr-btn--utama" data-qt="unduh" data-id="${q.id}">${ik('download', 16)} Unduh PDF</button>` : ''}</footer>`, 'lebar');
  const r = await renderDokFit(m, aset, { watermark: terbit ? '' : LBL[m.bahasa].wm }); await tungguGambar(r.host);
  const w = $('#qt-dokwrap'); if (!w) { r.host.remove(); return; }
  taruhPratinjau(w, r); r.host.remove(); const i = $('#qt-dokinfo'); if (i) i.textContent = r.n + ' halaman' + (r.d ? ' · tata letak dirapatkan otomatis' : '');
}
// Syarat kritis vendor (nomor 1-15) untuk lini yang dipakai penawaran ini, yang perlu tercakup di S&K.
const syaratKritisVendor = (q, bahasa = 'en') => {
  const vs = (MR() && MR().vendor) || [], hasil = [], seen = new Set();
  (q.baris || []).forEach(b => {
    if (b.jenis !== 'rate' || !b.vendorId || !b.liniKey) return;
    const k = b.vendorId + '|' + b.liniKey; if (seen.has(k)) return; seen.add(k);
    const v = vs.find(x => x.id === b.vendorId); if (!v) return;
    // syarat kritis = kalimat yang ditandai Kritis di form vendor (data lama tanpa tanda: nomor urut 1-4)
    const items = (v.tnc || []).filter(t => t.liniBisnisId === b.liniKey && (t.kritis !== undefined ? !!t.kritis : Number(t.urutan) >= 1 && Number(t.urutan) <= 4))
      .map(t => (bahasa === 'id' ? (t.isi || t.terjemahan || '') : (t.terjemahan || t.isi || '')).trim()).filter(Boolean);
    if (items.length) hasil.push({ vendor: v.nama || v.id, lini: namaLini(b.liniKey), items });
  });
  return hasil;
};
// Peringatan sebelum cetak/unduh: syarat kritis vendor harus tercakup di S&K penawaran. Tidak memblokir jika pengguna lanjut.
async function konfirmasiSyaratKritis(q) {
  const daftar = syaratKritisVendor(q);
  if (!daftar.length) return true;
  const isi = daftar.map(d => `<b>${esc(d.vendor)}</b> · ${esc(d.lini)}<ul class="mr-konfirm__daftar">${d.items.map(x => `<li>${esc(x)}</li>`).join('')}</ul>`).join('');
  return konfirmasi({ judul: 'Pastikan syarat kritis vendor tercakup', aksi: 'Sudah tercakup, cetak', isi: `Syarat kritis vendor berikut dipakai di penawaran ini. Pastikan S&K penawaran sudah memuat semuanya sebelum dicetak.${isi}` });
}
async function aksiUnduh(id, cara = 'unduh') {
  const q = Repo.baca(id); if (!q || !q.dokumenModel) return toast('Dokumen belum diterbitkan.', 'bahaya');
  if (!await konfirmasiSyaratKritis(q)) return;
  const namaT = namaFilePdf(q.dokumenModel);
  if (q.pdfUrl) { try { toast('Mengambil PDF tersimpan…'); const rs = await fetch(q.pdfUrl); if (!rs.ok) throw new Error('HTTP ' + rs.status); simpanBlob(await rs.blob(), namaT); try { await Repo.catatKeluaran(id, cara, namaT); } catch (er) { toast(`PDF terunduh, tetapi <b>catatan riwayat gagal tersimpan</b>.<br>${esc(er.message)}`, 'bahaya'); return segarSemua(); } toast(`PDF <b>${esc(namaT)}</b> (versi tersimpan) diunduh dan dicatat di riwayat.`); return segarSemua(); } catch (er) { /* gagal ambil: buat ulang dari isi yang dibekukan */ } }
  toast('Menyiapkan PDF…');
  let h; try { h = await buatPdf(q.dokumenModel, Repo.aset(id)); } catch (er) { return toast(`<b>PDF gagal dibuat.</b> Quotation tetap tersimpan; coba unduh lagi.<br>${esc(er.message)}`, 'bahaya'); }
  const nama = namaFilePdf(q.dokumenModel); h.pdf.save(nama);
  if (window.__ISL && window.__ISL.unggahBlob && bisaEdit() && !q.pdfUrl) { try { const u = await window.__ISL.unggahBlob('quotation_pdf/' + id + '.pdf', h.pdf.output('blob'), 'application/pdf'); await Repo.simpanPdfUrl(id, u); } catch (er) { toast(`PDF terunduh, tetapi <b>salinan di penyimpanan gagal</b> (akan dicoba lagi saat unduh berikutnya).<br>${esc(er.message)}`, 'bahaya'); } }
  try { await Repo.catatKeluaran(id, cara, nama); } catch (er) { toast(`PDF terunduh, tetapi <b>catatan riwayat gagal tersimpan</b>.<br>${esc(er.message)}`, 'bahaya'); return segarSemua(); }
  toast(`PDF <b>${esc(nama)}</b> (${h.halaman} halaman) diunduh dan dicatat di riwayat.`); segarSemua();
}
async function aksiEmail(id) {
  const q = Repo.baca(id); if (!q || !q.dokumenModel) return; const c = cust(q.customerId), m = q.dokumenModel, en = m.bahasa === 'en';
  const pic = c && (c.kontak.find(k => k.nama === q.picNama) || c.kontak[0]) || {};
  await aksiUnduh(id, 'email');
  const subj = `${m.judulDok} No. ${m.nomor} - ${q.judul}`;
  const body = en ? `Dear ${q.picNama || 'Sir/Madam'},\n\nPlease find attached our ${m.judulDok} No. ${m.nomor} regarding ${q.judul}.\nShould you have any questions, please let us know.\n\nSincerely,\n${m.penandatangan.nama}\nPT Indo Sukses Logistik`
    : `Yth. ${q.picNama || 'Bapak/Ibu'},\n\nTerlampir ${m.judulDok} No. ${m.nomor} perihal ${q.judul}.\nApabila ada hal yang perlu didiskusikan, silakan menghubungi kami.\n\nHormat kami,\n${m.penandatangan.nama}\nPT Indo Sukses Logistik`;
  window.open(`mailto:${encodeURIComponent(pic.email || '')}?subject=${encodeURIComponent(subj)}&body=${encodeURIComponent(body)}`, '_blank');
  toast(`Email dibuka. <b>Lampirkan file PDF yang baru diunduh</b>${pic.email ? '' : ' dan isi alamat penerima (PIC belum punya email)'}.`);
}
/* ---------- dialog keputusan (ditolak / tidak dipakai) ---------- */
function dialogKeputusan(q, o) {
  const d = document.createElement('div'); d.className = 'mr-konfirm';
  d.innerHTML = `<div class="mr-konfirm__kotak"><h3>${esc(o.judul)}</h3><div class="mr-konfirm__isi">
    <p style="margin:0 0 10px"><b>${esc(q.nomor)}</b> · ${esc(namaCust(q))}</p><p class="mr-sub" style="display:block;margin:0 0 10px">${o.info}</p>
    <label class="mr-f"><span>Tanggal</span><input data-x="tgl" type="date" value="${HARI_INI()}" max="${HARI_INI()}"></label>
    ${o.kategori ? `<label class="mr-f" style="margin-top:10px"><span>Alasan utama *</span><select data-x="kat"><option value="">Pilih alasan…</option>${Object.entries(o.kategori).map(([k, v]) => `<option value="${k}">${esc(v)}</option>`).join('')}</select></label>` : ''}
    <label class="mr-f" style="margin-top:10px"><span>${esc(o.label)} ${o.opsional ? '' : '*'}</span><textarea data-x="alasan" rows="3" placeholder="${esc(o.ph)}"></textarea></label>
    <p class="mr-galat" data-x="galat" hidden></p></div>
    <div class="mr-konfirm__aksi"><button class="mr-btn" data-x="batal">Batal</button><button class="mr-btn ${o.bahaya ? 'mr-btn--bahaya' : 'mr-btn--utama'}" data-x="ok">${esc(o.tombol)}</button></div></div>`;
  document.body.appendChild(d);
  const al = $('[data-x=alasan]', d), g = $('[data-x=galat]', d), ok = $('[data-x=ok]', d); al.focus();
  $('[data-x=batal]', d).onclick = () => d.remove();
  ok.onclick = async () => {
    const alasan = al.value.trim(), t = $('[data-x=tgl]', d).value, kat = o.kategori ? $('[data-x=kat]', d).value : '';
    if (o.kategori && !kat) { g.hidden = false; g.textContent = 'Pilih alasan utama supaya bisa dianalisis.'; return; }
    if (alasan.length < (o.minPanjang ?? 5)) { g.hidden = false; g.textContent = o.minTeks; return; }
    if (!t || t > HARI_INI()) { g.hidden = false; g.textContent = 'Isi tanggal (tidak boleh di masa depan).'; return; }
    ok.disabled = true; ok.textContent = 'Menyimpan…';
    try { await o.simpan(q.id, alasan, t, kat); } catch (er) { ok.disabled = false; ok.textContent = o.tombol; g.hidden = false; g.innerHTML = `<b>GAGAL menyimpan.</b> ${esc(er.message)}`; return; }
    d.remove(); toast(o.sukses(q)); segarSemua();
  };
}

/* ---------- bagikan lewat WhatsApp ---------- */
const nomorWa = t => { let d = String(t || '').replace(/\D/g, ''); if (!d) return ''; if (d.startsWith('0')) d = '62' + d.slice(1); else if (d.startsWith('8')) d = '62' + d; return d; };
/* Bagikan file langsung lewat menu bagi HP (WhatsApp, email, dan lainnya), PDF bawaan atau Word */
async function aksiBagikan(id, fmt) {
  const q = Repo.baca(id); if (!q || !q.dokumenModel) return toast('Dokumen belum diterbitkan.', 'bahaya');
  if (!await konfirmasiSyaratKritis(q)) return;
  const word = fmt === 'word', nama = word ? namaFileWord(q.dokumenModel) : namaFilePdf(q.dokumenModel); let blob;
  toast('Menyiapkan file…');
  try {
    if (word) blob = await buatDocx(q.dokumenModel, Repo.aset(id));
    else if (q.pdfUrl) { const rs = await fetch(q.pdfUrl); if (!rs.ok) throw new Error('HTTP ' + rs.status); blob = await rs.blob(); }
    else { const h = await buatPdf(q.dokumenModel, Repo.aset(id)); blob = h.pdf.output('blob'); }
  } catch (er) { return toast(`<b>File gagal disiapkan.</b> ${esc(er.message)}`, 'bahaya'); }
  const f = new File([blob], nama, { type: word ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' : 'application/pdf' });
  if (navigator.canShare && navigator.canShare({ files: [f] })) {
    try { await navigator.share({ files: [f], title: nama }); try { await Repo.catatKeluaran(id, word ? 'word' : 'bagikan', nama); } catch (er) { } segarSemua(); return; }
    catch (er) { if (er && er.name === 'AbortError') return; }
  }
  simpanBlob(blob, nama); toast('Perangkat ini belum bisa membagikan file langsung, jadi file diunduh. Lampirkan secara manual.');
}
async function aksiWa(id) {
  const q = Repo.baca(id); if (!q || !q.dokumenModel) return; const c = cust(q.customerId), m = q.dokumenModel, en = m.bahasa === 'en';
  const k = (c && (c.kontak.find(z => norm(z.nama) === norm(q.picNama)) || c.kontak[0])) || {}, no = nomorWa(q.picTelp || k.telp);
  await aksiUnduh(id, 'wa');
  const teks = en ? `Dear ${q.picNama || 'Sir/Madam'},\n\nPlease find our ${m.judulDok} No. ${m.nomor} regarding ${q.judul} (PDF attached).\nPlease let us know if you have any questions.\n\nBest regards,\n${m.penandatangan.nama}\nPT Indo Sukses Logistik`
    : `Yth. ${q.picNama || 'Bapak/Ibu'},\n\nBersama ini kami kirimkan ${m.judulDok} No. ${m.nomor} perihal ${q.judul} (PDF terlampir).\nApabila ada hal yang perlu didiskusikan, silakan menghubungi kami.\n\nHormat kami,\n${m.penandatangan.nama}\nPT Indo Sukses Logistik`;
  window.open(`https://wa.me/${no}?text=${encodeURIComponent(teks)}`, '_blank');
  toast(`WhatsApp dibuka${no ? '' : ' (PIC belum punya nomor telepon, pilih kontaknya sendiri)'}. <b>Lampirkan file PDF yang baru diunduh</b> sebelum mengirim.`);
}

