/* ---------- ekspor Excel semua quotation (cadangan dan laporan) ---------- */
function ekspor() {
  if (!window.XLSX) return toast('Pustaka Excel belum termuat. Periksa koneksi internet lalu muat ulang halaman.', 'bahaya');
  const all = Repo.semua().sort((a, b) => String(b.dikirim || b.dibuat).localeCompare(String(a.dikirim || a.dibuat))), X = amanXLSX(window.XLSX);
  const hdr = all.map(q => { const rg = rgQ(q); return { 'Nomor': q.nomor || q.labelDraf, 'Sumber': 'Sistem', 'Revisi ke': q.revisiKe || 0, 'Status': AQ.status[q.status], 'Customer': namaCust(q), 'PIC': q.picNama || '', 'Perihal': q.judul,
    'Bahasa': q.bahasa === 'en' ? 'English' : 'Indonesia', 'Template harga': q.tipe === 'project' ? 'Harga total project' : 'Harga per layanan', 'Tanggal dibuat': q.dibuat || '', 'Tanggal terbit': q.tanggalTerbit || q.dikirim || '', 'Berlaku sampai': q.berlakuSampai || '', 'Tanggal keputusan': q.diputuskan || '',
    'Alasan utama ditolak': q.kategoriTolak ? AQ.alasanTolak[q.kategoriTolak] : '', 'Catatan penolakan / tidak dipakai': q.alasanDitolak || q.alasanTidakDipakai || '', 'Hari tanpa kabar': R.hariTanpaKabar(q) ?? '',
    'Total jual (Rp)': rg.totalJual, 'Total modal (Rp)': rg.totalModal ?? '', 'Margin (Rp)': rg.marginRp ?? '', 'Margin (% dari modal)': rg.marginPersen === null ? '' : Math.round(rg.marginPersen * 10) / 10, 'Target tertimbang (%)': rg.targetTertimbang === null ? '' : Math.round(rg.targetTertimbang * 10) / 10, 'Selisih dari target (poin)': rg.selisihPoin === null ? '' : Math.round(rg.selisihPoin * 10) / 10 }; });
  const det = []; all.forEach(q => q.baris.forEach((b, i) => det.push({ 'Nomor': q.nomor || q.labelDraf, 'Customer': q.customerNama || '', 'No baris': i + 1, 'Jenis': b.jenis === 'tambahan' ? 'Biaya tambahan' : 'Layanan', 'Lini bisnis': b.liniNama || namaLini(b.liniKey), 'Uraian': b.item, 'Satuan': b.satuan, 'Jumlah': b.qty, 'Modal /satuan (Rp)': b.modal ?? '', 'Harga jual /satuan (Rp)': b.jual, 'Subtotal jual (Rp)': R.sub(b) })));
  /* riwayat PDF (dibuat di luar sistem): kolom yang tidak tercatat dibiarkan kosong */
  const rw = rwSemua(), kosong = Object.fromEntries(Object.keys(hdr[0] || {}).map(k => [k, '']));
  rw.forEach(x => { const c = cust(rwCid(x)); hdr.push({ ...kosong, 'Nomor': x.nomor || '', 'Sumber': 'Riwayat PDF', 'Revisi ke': 0, 'Status': RW_STATUS[x.status] || x.status, 'Customer': c ? c.nama : (x.customerNama || ''), 'Perihal': namaLini(x.lini) || '',
    'Tanggal terbit': x.tanggalKirim || '', 'Tanggal keputusan': rwPutus(x), 'Hari tanpa kabar': RW_KELOMPOK[x.status] === 'terkirim' ? (rwHari(x) ?? '') : '', 'Total jual (Rp)': x.nilai || '', 'File PDF': x.pdfNama || '' }); });
  const wb = X.utils.book_new(); X.utils.book_append_sheet(wb, X.utils.json_to_sheet(hdr), 'Quotation'); X.utils.book_append_sheet(wb, X.utils.json_to_sheet(det), 'Baris layanan');
  const nama = `Quotation_ISL_${HARI_INI()}.xlsx`; X.writeFile(wb, nama);
  toast(`<b>${esc(nama)}</b> diunduh (${all.length} quotation${rw.length ? ` + ${rw.length} riwayat PDF` : ''}, ${det.length} baris). File ini memuat <b>modal dan margin</b>; jangan dibagikan ke luar tim.`);
}

/* ---------- PENGATURAN DOKUMEN ---------- */
const GAYA_NOMOR = [{ n: 'Modern', f: '{prefix}/{jenis}/{YY}{MM}/{seq}' }, { n: 'Ringkas', f: '{jenis}-{YY}{MM}-{seq}' }, { n: 'Klasik (seperti contoh lama)', f: '{seq}/{seri}/{RM}/{YYYY}' }];
/* nomor terakhir yang BERLAKU di periode berjalan: isian lama dari bulan atau tahun sebelumnya tidak dihitung lagi */
const awalBerlaku = (p, s) => { s = s || {}; const a = Number(s.awal) || 0; return (a && s.periode === Repo.kunciUrut(HARI_INI(), s.kode, p.nomor.reset)) ? a : 0; };
const pratinjauNomor = (format, p, urut = 7, kode = 'QL-ISL') => { const simpan = PENG.nomor; PENG.nomor = { ...p.nomor, format }; try { return R.nomorResmi(urut, HARI_INI(), kode); } finally { PENG.nomor = simpan; } };
const getPath = (o, p) => p.split('.').reduce((x, k) => (x ? x[k] : undefined), o);
const setPath = (o, p, v) => { const a = p.split('.'), l = a.pop(); const t = a.reduce((x, k) => x[k], o); t[l] = v; };
/* ---------- markup per lini bisnis (Pengaturan dokumen) ---------- */
/* warna rekomendasi markup: di bawah 10% merah, 10 sampai di bawah 20% kuning, 20% sampai 30% dan di atas 30% hijau. Hanya peringatan. */
function markupNilaiKelas(n) { return n < 10 ? 'merah' : n < 20 ? 'kuning' : 'hijau'; }
const MARKUP_KET = { merah: 'Di bawah 10%: markup terlalu rendah, periksa lagi.', kuning: '10% sampai di bawah 20%: markup tipis.', hijau: 'Markup sehat.' };
function markupKartuSegarkan(kartu) {
  const inp = kartu.querySelector('[data-mk]'); const raw = String(inp.value).replace(',', '.').trim();
  const n = raw === '' ? AQ.markupBawaan : Number(raw); const kelas = isFinite(n) && n >= 0 ? markupNilaiKelas(n) : null;
  kartu.classList.remove('is-merah', 'is-kuning', 'is-hijau'); if (kelas) kartu.classList.add('is-' + kelas);
  const ket = kartu.querySelector('.qt-mk-ket'); if (ket && kelas) ket.textContent = MARKUP_KET[kelas];
}
function htmlMarkupLini(ed) {
  const lini = (MR() && MR().lini) || [];
  if (!lini.length) return '<p class="mr-sub">Belum ada lini bisnis di Master Rate.</p>';
  return `<div class="qt-mk-kisi">${lini.map(l => { const t = targetLini(l.id); const tampil = t === null ? '' : String(t).replace('.', ','); const nama = esc(l.nama || l.id); return `<div class="qt-mk-kartu is-${markupNilaiKelas(t === null ? AQ.markupBawaan : t)}"><div class="qt-mk-nama"><span>${nama}${l.aktif === false ? ' <em class="mr-sub">(nonaktif)</em>' : ''}</span>${ed ? `<button type="button" class="qt-mk-edit" data-mk-edit="${esc(l.id)}" aria-label="Ubah markup ${nama}" title="Ubah markup">${ik('edit', 13)}</button>` : ''}</div><div class="qt-mk-step"><button type="button" class="qt-mk-btn" data-mk-step="${esc(l.id)}" data-delta="-1" ${ed ? '' : 'disabled'} aria-label="Kurangi 1% ${nama}">−</button><label class="qt-mk-in"><input data-mk="${esc(l.id)}" inputmode="decimal" value="${tampil}" placeholder="${AQ.markupBawaan}" ${ed ? '' : 'disabled'} autocomplete="off" aria-label="Rekomendasi markup ${nama}"><b>%</b></label><button type="button" class="qt-mk-btn" data-mk-step="${esc(l.id)}" data-delta="1" ${ed ? '' : 'disabled'} aria-label="Tambah 1% ${nama}">+</button></div><div class="mr-sub qt-mk-ket">${MARKUP_KET[markupNilaiKelas(t === null ? AQ.markupBawaan : t)]}</div></div>`; }).join('')}</div>
    ${ed ? `<div class="qt-tbaks" style="margin:12px 0 0"><button type="button" class="mr-btn mr-btn--kecil mr-btn--utama" data-qt="pg-markup-simpan">${ik('cek', 14)} Simpan markup</button></div>` : ''}`;
}
document.addEventListener('input', ev => { const inp = ev.target.closest && ev.target.closest('[data-mk]'); if (inp) markupKartuSegarkan(inp.closest('.qt-mk-kartu')); });
document.addEventListener('click', ev => {
  const ed = ev.target.closest('[data-mk-edit]');
  if (ed) { const inp = document.querySelector(`[data-mk="${ed.dataset.mkEdit}"]`); if (inp) { inp.focus(); inp.select(); } return; }
  const st = ev.target.closest('[data-mk-step]'); if (!st) return;
  const inp = document.querySelector(`[data-mk="${st.dataset.mkStep}"]`); if (!inp) return;
  const mentah = String(inp.value).replace(',', '.').trim(), dasar = mentah === '' ? AQ.markupBawaan : (Number(mentah) || 0);  /* kosong = nilai bawaan, bukan 0 */
  const nilai = Math.min(1000, Math.max(0, dasar + Number(st.dataset.delta)));
  inp.value = String(Math.round(nilai * 10) / 10).replace('.', ','); inp.dispatchEvent(new Event('input', { bubbles: true }));
});
async function simpanMarkupSemua(tombol) {
  const ubah = [], salah = [];
  $$('[data-mk]').forEach(inp => {
    const t = inp.value.trim().replace(',', '.'), n = t === '' ? null : Number(t);
    if (t !== '' && (!isFinite(n) || n < 0 || n > 1000)) { salah.push(inp.closest('label').querySelector('span').textContent); return; }
    if (n !== targetLini(inp.dataset.mk)) ubah.push([inp.dataset.mk, n]);
  });
  if (salah.length) return toast(`Markup diisi angka 0 atau lebih (persen dari modal), atau dikosongkan: <b>${esc(salah.join(', '))}</b>.`, 'bahaya');
  if (!ubah.length) return toast('Tidak ada markup yang berubah.');
  tombol.disabled = true; const label = tombol.innerHTML; tombol.textContent = 'Menyimpan…';
  const gagal = [];
  for (const [k, n] of ubah) { try { await simpanMarkup(k, n); } catch (er) { gagal.push(`${namaLini(k)}: ${er.message}`); } }
  tombol.disabled = false; tombol.innerHTML = label;
  if (gagal.length) toast(`<b>${ubah.length - gagal.length} tersimpan, ${gagal.length} GAGAL.</b><br>${esc(gagal[0])}`, 'bahaya');
  else toast(`<b>Markup ${ubah.length} lini tersimpan.</b> Batas harga aman akun sales ikut diperbarui.`);
  gambar();
}
/* kartu Pengaturan dokumen per peran. Master melihat semua; admin dan sales hanya kartu yang diizinkan. */
/* tanda tangan dan cap: foto di atas kertas diubah jadi PNG transparan (latar kertas hilang, tinta tetap) */
async function gambarAset(f) {
  if (!/^image\//.test(f.type)) throw new Error('Pilih file gambar (PNG, JPG, atau WEBP).');
  if (f.size > 4 * 1024 * 1024) throw new Error('Ukuran gambar maksimal 4 MB.');
  const d = window.__islHapusLatar ? await window.__islHapusLatar(f) : null;
  if (!d) throw new Error('Latar foto tidak cukup terang untuk dipisah. Foto tanda tangan atau cap di atas kertas putih dengan cahaya merata.');
  return d;
}
