const PGD_ADMIN = ['kopsurat', 'penomoranquotation', 'templateperlinibisni', 'templatesaya', 'satuanquotation', 'tabeldokumenperlinib', 'pengingatrekapkegiat', 'penandatangantandata', 'kalimatstandar', 'pustaka'];
