  if (Q.pd) { Q.pd.tnc = clone(PENG.tnc); Q.pd.kalimatLini = clone(PENG.kalimatLini || {}); Q.pd.syaratLini = clone(PENG.syaratLini || {}); Q.pd.templateLini = clone(PENG.templateLini || {}); }
