  const layanan = norm(nama).replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  if (MR().tarif.some(t => t.liniBisnisId === TL.lini && t.layanan === layanan && t.satuanKode === sat)) return galatPanel(`<b>Layanan ini sudah ada</b> di lini ${esc(namaLini(TL.lini))} dengan satuan yang sama. Pilih dari daftar Master Rate saja.`);
