    const thn = +HARI_INI().slice(0, 4), tahunOpt = []; for (let y = Math.min(thn - 3, tahun); y <= Math.max(thn + 8, tahun); y++) tahunOpt.push(y);
    sc.innerHTML = `<div class="tg-pop" role="dialog" aria-modal="true" aria-label="Pilih tanggal"><div class="tg-kep"><button type="button" class="tg-nav" data-n="-1" aria-label="Bulan sebelumnya">‹</button><select class="tg-sel" data-s="b" aria-label="Bulan">${NAMA_BLN.map((n, i) => `<option value="${i}" ${i === bulan ? 'selected' : ''}>${n}</option>`).join('')}</select><select class="tg-sel" data-s="t" aria-label="Tahun">${tahunOpt.map(y => `<option ${y === tahun ? 'selected' : ''}>${y}</option>`).join('')}</select><button type="button" class="tg-nav" data-n="1" aria-label="Bulan berikutnya">›</button></div>
      <div class="tg-hr">${NAMA_HRI.map(h => `<span>${h}</span>`).join('')}</div><div class="tg-gr">${sel.join('')}</div>
      <div class="tg-kaki"><button type="button" class="mr-btn mr-btn--kecil" data-a="ini">Hari ini</button>${wajib ? '' : '<button type="button" class="mr-btn mr-btn--kecil" data-a="kosong">Kosongkan</button>'}<span class="mr-ruang"></span><button type="button" class="mr-btn" data-a="batal">Batal</button><button type="button" class="mr-btn mr-btn--utama" data-a="ok">OK</button></div></div>`;
