const namaFileWord = m => namaFilePdf(m).replace(/\.pdf$/i, '.docx');
function simpanBlob(blob, nama) { const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = nama; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1500); }

/* =============================== S. WORD DI ALUR QUOTATION: unduh, manual dari daftar, dokumen final =============================== */
async function aksiUnduhWord(id, cara = 'unduh') {
  const q = Repo.baca(id); if (!q || !q.dokumenModel) return toast('Dokumen belum diterbitkan.', 'bahaya');
  toast('Menyiapkan file Word…'); let blob;
  try { blob = await buatDocx(q.dokumenModel, Repo.aset(id)); } catch (er) { return toast(`<b>File Word gagal dibuat.</b> Quotation tetap tersimpan; coba unduh lagi.<br>${esc(er.message)}`, 'bahaya'); }
  const nama = namaFileWord(q.dokumenModel); simpanBlob(blob, nama);
  try { await Repo.catatKeluaran(id, 'word', nama); } catch (er) { toast(`File Word terunduh, tetapi <b>catatan riwayat gagal tersimpan</b>.<br>${esc(er.message)}`, 'bahaya'); return segarSemua(); }
  toast(`File Word <b>${esc(nama)}</b> diunduh dan dicatat di riwayat. Tabel dan syarat bisa diubah manual di Word.`); segarSemua();
}
/* ----- Word manual dari halaman daftar ----- */
