  if (b.sumber === 'bebas') { b.item = g('item').trim(); b.satuan = satuanKanon(g('satuan')); } b.volume = angkaQty(g('volume')); b.jual = angkaRp(g('jual')); b.modal = angkaRp(g('modal'));
