const rateBerlakuPada = (cid, tgl1, tgl2) => { const m = new Map(); S.rates.filter(r => r.cid === cid && r.appr <= tgl2 && (!akhirBerlaku(r) || akhirBerlaku(r) >= tgl1)).forEach(r => { const k = kunciGrup(r), x = m.get(k); if (!x || r.appr > x.appr) m.set(k, r); }); return [...m.values()]; };
