const rateDipakai = r => DB.orders.some(o => o.cid === r.cid && o.baris.some(b => b.sumber === 'rate' && b.sumberId && (b.sumberId === r.id || (() => { const x = S.rates.find(z => z.id === b.sumberId); return x && kunciGrup(x) === kunciGrup(r); })())));
