  S.rates.filter(r => statusRate(r) === 'aktif' && !rateDipakai(r)).forEach(r => hasil.push({ jenis: 'rate', cid: r.cid, nama: r.item, sub: `${namaLini(r.lini, r.liniNama)} · ${r.satuan}`, appr: r.appr, hari: selisih(r.appr), nilai: r.jual }));
  S.paket.filter(p => CU.statusPaket(p) === 'aktif' && !paketDipakai(p)).forEach(p => hasil.push({ jenis: 'paket', cid: p.cid, nama: p.nama, sub: `Paket project · ${p.komponen.length} komponen`, appr: p.appr, hari: selisih(p.appr), nilai: p.komponen.reduce((s, k) => s + k.jual * (k.qty > 0 ? k.qty : 1), 0) }));
