  const hi = HARI_INI(), thnMax = +hi.slice(0, 4), blnOpt = BULAN.id.map((n, i) => `<option value="${i + 1}" ${st.bln === i + 1 ? 'selected' : ''}>${n}</option>`).join(''), thnOpt = [...Array(6)].map((_, i) => thnMax - i).map(y => `<option value="${y}" ${st.thn === y ? 'selected' : ''}>${y}</option>`).join('');
