const orderRekapP = (cid, mulai, akhir) => DB.orders.find(o => o.cid === cid && o.jenis === 'rekap' && (o.periode ? (o.periode.mulai === mulai && o.periode.akhir === akhir) : (mulai.slice(0, 7) === bulanKey(o.tanggal) && mulai.endsWith('-01') && akhir === akhirBulan(mulai.slice(0, 7)))));
