  const out = []; kunci.forEach(arr => { arr.sort((x, y) => x.appr.localeCompare(y.appr)); arr.forEach(r => { const nx = r.digantikanOleh ? S.rates.find(z => z.id === r.digantikanOleh) : null, akhirEf = r.sampai || (nx ? tambahHariIso(nx.appr, -1) : null); out.push({ r, banyak: arr.length > 1, dari: r.appr > a ? r.appr : a, sampai: akhirEf && akhirEf < b ? akhirEf : b }); }); }); return out;
