  <div class="mr-panel__isi">${dlSatuanHtml()}<div class="qt-grid"><label class="mr-f qt-c6"><span>Customer *</span><select id="rk-cust"><option value="">Pilih customer…</option>${S.customers.filter(c => c.status !== 'nonaktif').sort((a, b) => a.nama.localeCompare(b.nama)).map(c => `<option value="${c.id}" ${c.id === RK.cid ? 'selected' : ''}>${esc(c.nama)}</option>`).join('')}</select></label>
    <div class="mr-f qt-c6"><span>&nbsp;</span><div class="qt-aksi" style="justify-content:flex-start;flex-wrap:wrap"><button type="button" class="mr-btn" data-or="rk-salin">${ik('salin', 14)} Salin periode sebelumnya</button><button type="button" class="mr-btn" data-or="rk-xlsx">${ik('download', 14)} Lembar Excel customer ini</button></div></div></div>
    <div id="rk-periode" style="margin-top:10px"></div><div id="rk-isi" style="margin-top:12px"></div><p class="mr-galat" id="pn-galat" hidden></p></div>
