  if (!RK.cid) err.push('Pilih customer.'); if (st.jenis === 'rentang' && (!st.dari || !st.sampai)) err.push('Isi tanggal dari dan sampai.'); if (st.akhir < st.mulai) err.push('Tanggal akhir tidak boleh sebelum tanggal awal.'); if (st.mulai > hi) err.push('Periode tidak boleh seluruhnya di masa depan.');
