/* Sebelum terbit: user memeriksa S&K lebih dulu. Tidak ditanya ulang selama S&K tidak berubah sejak terakhir dikonfirmasi. */
function tncJejak(e) { const b = e.bahasa || 'id', g = R.tncGrup(e, b, { berlaku: fmtTglDok(e.berlakuSampai, b) }, R.bagianTabel(e, b).termasuk); return b + '|' + g.map(x => x.items.map(i => i.teks).join('\u241f')).join('\u241e'); }
async function periksaTncSebelumTerbit(e) {
  const jejak = tncJejak(e); if (e.tncDiperiksa === jejak) return true;
  const b = e.bahasa || 'id', grup = R.tncGrup(e, b, { berlaku: fmtTglDok(e.berlakuSampai, b) }, R.bagianTabel(e, b).termasuk), butir = grup.flatMap(g => g.items);
  /* Distribusi: biaya pembatalan, biaya inap, dan waktu tunggu hanya diatur lewat teks S&K (tidak ada kolom). Butirnya disorot dan diingatkan sebelum PDF dicetak atau diterbitkan. */
  const distribusi = !!(e.formLini && e.formLini.lini === 'distribusi_kecil'), RE_TEKS = /pembatalan|biaya inap|waktu tunggu|cancell?ation|overnight|waiting time/i;
  const angka = t => esc(t).replace(/(Rp\s?[\d.,]+|\d+(?:[.,]\d+)?\s*(?:jam|hours?|WIB))/gi, '<b>$1</b>'), nSorot = 0;
  const ok = await konfirmasi({ judul: distribusi ? 'Periksa syarat dan ketentuan (biaya yang diatur lewat teks)' : 'Periksa syarat dan ketentuan', aksi: distribusi ? 'Sudah sesuai, lanjutkan' : 'S&K sudah benar, lanjutkan', batal: 'Kembali, ubah S&K',
    isi: `${distribusi ? `<div class="mr-konfirm__ingat"><b>Biaya pembatalan, biaya inap, dan waktu tunggu hanya diatur lewat teks S&amp;K</b> (tidak ada kolom atau fitur khusus untuk mengubahnya). Cek nominal dan jam berikut, sesuaikan dengan kesepakatan customer ini. Kalau perlu diubah, pilih <b>Kembali, ubah S&amp;K</b>; kalau sudah sesuai, lanjutkan.<ul class="mr-konfirm__ingat-d">${butir.filter(i => RE_TEKS.test(i.teks)).map(i => `<li>${angka(i.teks)}</li>`).join('')}</ul></div>` : ''}<p style="margin:0 0 8px">Ini ${butir.length} butir S&K yang akan tercetak di dokumen. Pastikan sudah sesuai penawaran ini.</p><ol class="mr-konfirm__daftar mr-konfirm__no">${butir.map(i => `<li${distribusi && RE_TEKS.test(i.teks) ? ' class="mr-konfirm__sorot"' : ''}>${distribusi ? angka(i.teks) : esc(i.teks)}</li>`).join('') || '<li><i>(tidak ada butir)</i></li>'}</ol>` });
  if (!ok) { const d = $('details[data-det=tnc]'); if (d) { d.open = true; d.scrollIntoView({ block: 'start', behavior: 'smooth' }); } return false; }
  e.tncDiperiksa = jejak; return true;
}
/* Pop-up sebelum terbit: ada layanan yang harga jualnya di bawah tarif minimum (modal + markup lini). Hanya peringatan; "Tetap terbitkan" selalu boleh.
   Tidak ditanya ulang selama daftar dan angkanya sama dengan yang sudah disetujui. */
async function periksaHargaMinimum(e) {
  const daftar = R.hargaDiBawahMin(e); if (!daftar.length) { e.hargaMinDisetujui = ''; return true; }
  const sig = JSON.stringify(daftar.map(x => [x.item, x.jual, x.min])); if (e.hargaMinDisetujui === sig) return true;
  const jauh = daftar.filter(x => x.persen >= 10).length, tampil = daftar.slice(0, 10).map(x => `<li class="qt-min__i"><b>${esc(x.item)}</b><span>Harga jual <b class="cu-neg">${rp(x.jual)}</b> · minimum <b>${rp(x.min)}</b></span><span class="cu-neg">Kurang ${rp(x.kurang)} (${fmtPct(x.persen)} di bawah minimum)</span></li>`).join('') + (daftar.length > 10 ? `<li class="qt-min__i">dan ${daftar.length - 10} layanan lain</li>` : '');
  const ok = await konfirmasi({ judul: `Harga jual di bawah tarif minimum`, aksi: 'Tetap terbitkan', batal: 'Kembali, periksa harga',
    isi: `<p style="margin:0 0 8px">${daftar.length === 1 ? '<b>1 layanan</b>' : `<b>${daftar.length} layanan</b>`} dijual di bawah tarif minimum (modal Master Rate + markup lini).${jauh ? ` ${jauh === 1 ? 'Satu di antaranya' : jauh + ' di antaranya'} jauh di bawah (10% atau lebih).` : ''} Margin quotation ini lebih tipis dari target.</p>
      <ul class="qt-min">${tampil}</ul>
      <p class="mr-sub" style="display:block;margin:8px 0 0">Penawaran <b>tetap bisa diterbitkan</b> kalau harga ini memang sudah disetujui. Pilih <b>Kembali</b> untuk memperbaiki harganya dulu.</p>` });
  if (!ok) { const el = document.querySelector('#fl-root [data-rendah], .qt-jual-rendah'); if (el) { el.scrollIntoView({ block: 'center', behavior: 'smooth' }); try { el.focus({ preventScroll: true }); } catch (er) { } } return false; }
  e.hargaMinDisetujui = sig; return true;
}
async function aksiKirim(btn, format = 'pdf') {
  bacaForm(); const e = Q.edit, err = [...R.validasiSimpan(e), ...R.validasiKirim(e)];
  if (err.length) return galatHalaman('<b>Belum bisa diterbitkan:</b><br>' + err.map(esc).join('<br>'));
  $('#qt-galat').hidden = true;
  if (e.formLini && window.ISLFL && window.ISLFL.konfirmasiReferensi && !(await window.ISLFL.konfirmasiReferensi(e))) return;
  if (e.formLini && window.ISLFL && window.ISLFL.konfirmasiKosong && !(await window.ISLFL.konfirmasiKosong(e))) return;
  if (!(await periksaTncSebelumTerbit(e))) return;
  if (!(await periksaHargaMinimum(e))) return;
  if (!cariCustomer(e)) { const mirip = cariMirip(e); if (mirip.length && !await konfirmasi({ judul: 'Mungkin customer yang sama?', aksi: 'Tetap buat customer baru', isi: `“${esc(e.customerNama)}” belum terdaftar, tetapi mirip dengan: <b>${mirip.map(m => esc(m.nama)).join(', ')}</b>. Kalau itu orang yang sama, batalkan lalu pakai nama yang sudah ada supaya rate dan riwayatnya tidak terpisah.` })) return; }
  const rg = R.ringkas(e.baris, R.targetLive), ws = R.peringatan(rg).filter(w => w.j !== 'info'), nomor = Repo.nomorBerikut(e.seri = seriValid(e.seri), format === 'docx');
  const word = format === 'docx';
  const kodeSeri = e.seri, terakhir = Math.max(DB.urutTahun[Repo.kunciUrut(HARI_INI(), kodeSeri)] || 0, Repo.awalSeri(kodeSeri));
  const ok = await konfirmasi({ judul: word ? 'Terbitkan quotation dan unduh Word?' : 'Terbitkan quotation dan unduh PDF?', bahaya: rg.rugiTotal, aksi: word ? 'Beri nomor, kunci, dan unduh Word' : 'Beri nomor, kunci, dan unduh PDF',
    pintas: k => { if (k === 'penomoran') bukaPenomoran(); },
    isi: `<div class="qt-nomorinfo"><span class="qt-nomorinfo__l">Nomor resmi yang akan dipakai</span><b class="qt-nomorinfo__n">${esc(nomor)}</b><small>Nomor terakhir yang terpakai di periode ini: <b>${terakhir}</b>.</small>${kelolaSaja() ? `<button type="button" class="qt-link" data-pintas="penomoran">Nomor tidak sesuai urutan? Atur penomoran</button>` : '<small>Nomor tidak sesuai urutan? Minta master atau admin mengaturnya di Pengaturan dokumen &gt; Penomoran.</small>'}</div>
      <p style="margin:0 0 8px">${e.bahasa === 'en' ? 'English' : 'Indonesia'} · ${e.tipe === 'project' ? 'harga total project' : 'harga per layanan'}. Setelah ini quotation <b>terkunci</b> dan isi dokumennya dibekukan; mengubahnya lewat “Buat revisi” (nomor baru).</p>
      <p style="margin:0 0 8px">Total harga jual <b>${rp(rg.totalJual)}</b>${rg.marginRp !== null ? `, margin <b>${rpS(rg.marginRp)}</b> (${fmtPct(rg.marginPersen)} dari modal)` : ''}.</p>
      ${ws.length ? `<ul style="margin:0 0 8px;padding-left:18px">${ws.map(w => `<li>${esc(w.t)}</li>`).join('')}</ul>` : ''}
      ${R.kopBelumDiisi() ? `<p class="mr-sub" style="display:block;margin:0 0 8px;color:var(--mr-warn)">${ik('peringatan', 13)} Data kop atau penandatangan masih contoh. Dokumen akan terbit dengan isian itu.</p>` : ''}
      ${word ? `<p class="mr-sub" style="display:block;margin:0 0 8px">${ik('info', 13)} File Word bisa diubah manual setelah diunduh. <b>Perubahan di Word tidak otomatis masuk ke sistem</b>; sistem menyimpan isi saat terbit, nomor, dan status. Saat disetujui, harga bisa dikoreksi sesuai dokumen akhir.</p>` : ''}<p class="mr-sub" style="display:block;margin:0">Pengiriman email dilakukan dari tombol “Unduh dan buka email” di halaman ini.</p>` });
  if (!ok) return;
  const pulih = sibuk(btn, 'Menyimpan…'); let x;
  e.jalur = word ? 'word' : 'sistem';
  try { await Repo.simpanDraf(e); x = await Repo.kirim(Repo.baca(e.id)); Q.id = x.id; Q.edit = null; Q.kotor = false; }
  catch (er) { pulih(); return galatHalaman(`<b>GAGAL.</b> Quotation belum terbit dan nomor tidak terpakai.<br>${esc(er.message)}`); }
  toast(`Quotation <b>${esc(x.nomor)}</b> terbit, terkunci, dan terverifikasi.${x._custBaru ? ` <b>${esc(x.customerNama)}</b> ditambahkan ke Master Customer (status Prospek).` : (x._custTerhubung ? ` Dihubungkan ke customer <b>${esc(x.customerNama)}</b> yang sudah ada di Master Customer.` : '')}`); gambar();
  await simpanSalinanPdf(x.id);
  if (word) await aksiUnduhWord(x.id, 'unduh'); else await aksiUnduh(x.id, 'unduh');
}
async function aksiHapus() {
  if (dilarangHapus()) return toast(PESAN_HAPUS_MASTER, 'bahaya');
  const q = Q.edit || Repo.baca(Q.id); if (!q) return;
  const ok = await konfirmasi({ judul: 'Hapus draf ini?', bahaya: true, aksi: 'Hapus permanen', isi: `<b>${esc(q.labelDraf || 'Draf baru')}</b> · ${esc(q.judul || 'tanpa judul')} dihapus permanen. Nomor resmi tidak terpengaruh karena draf belum bernomor.` });
  if (!ok) return;
  if (!q.id) { Q.edit = null; Q.kotor = false; Q.view = 'list'; return gambar(); }
  try { await Repo.hapusDraf(q.id); } catch (er) { return toast(`<b>GAGAL menghapus.</b><br>${esc(er.message)}`, 'bahaya'); }
  Q.edit = null; Q.kotor = false; Q.view = 'list'; Q.id = null; toast('Draf terhapus dan terverifikasi.'); gambar();
}
async function aksiTurunan(jenis) {
  const q = Repo.baca(Q.id); if (!q) return;
  if (jenis === 'revisi') { const ada = Repo.semua().find(x => x.indukId === q.id && x.status === 'draf'); if (ada) { toast('Sudah ada draf revisi untuk quotation ini. Dibuka sekarang.'); return bukaId(ada.id); } }
  const baru = R.turunan(q, jenis);
  try { const x = await Repo.simpanDraf(baru); toast(`${jenis === 'revisi' ? 'Draf revisi' : 'Duplikat'} <b>${esc(x.labelDraf)}</b> dibuat dan terverifikasi. ${jenis === 'revisi' ? 'Nomor baru diberikan saat ditandai terkirim.' : ''}`); bukaId(x.id); }
  catch (er) { toast(`<b>GAGAL membuat salinan.</b><br>${esc(er.message)}`, 'bahaya'); }
}

/* ---------- panel: pilih dari Master Rate ---------- */
function panelMR() {
  bacaForm(); const e = Q.edit; if (!e) return; Q.ditambah = 0;
  const lini = Object.entries(liniResmi());
  bukaPanel(`<header class="mr-panel__kepala"><div><h2>Tambah dari Master Rate</h2><p class="mr-sub">Modal terisi otomatis. Harga jual saran = modal + markup lini (Pengaturan dokumen).</p></div><button class="mr-ikonbtn" data-aksi="tutup-layer" aria-label="Tutup">${ik('tutup')}</button></header>
  <div class="mr-panel__isi">
    <div class="qt-grid"><label class="mr-f qt-c6"><span>Lini bisnis</span><select id="qp-lini">${opt(lini, lini[0] ? lini[0][0] : '')}</select></label>
      <label class="mr-f qt-c6"><span>Cari layanan atau rute</span><input id="qp-q" placeholder="Mis. ancol, storage, 20ft" autocomplete="off"></label></div>
    <div id="qp-hasil" class="qt-pick"></div>
  </div>
  <footer class="mr-panel__kaki"><span class="mr-sub" id="qp-info" style="margin:0 auto 0 0">Belum ada yang ditambahkan.</span><button class="mr-btn mr-btn--utama" data-aksi="tutup-layer">Selesai</button></footer>`);
  isiPicker();
}
const ringkasDim = t => Object.values(t.dimensi || {}).filter(Boolean).map(v => String(v).replace(/_/g, ' ').replace(/^(\d+)\s?ft$/i, '$1 ft')).join(' · ');
/* nama lokasi untuk dibaca orang: kode yang sama dengan vendor tidak diulang (vendor sudah tampil), awalan vendor dibuang */
const lokasiRapi = t => { const l = String(t.lokasiId || ''), v = String(t.vendorId || ''); if (!l || l === v) return ''; const s = l.startsWith(v + '_') ? l.slice(v.length + 1) : l; return s.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()); };
function isiPicker() {
  const box = $('#qp-hasil'); if (!box) return;
  const lini = $('#qp-lini').value, q = norm($('#qp-q').value), m = MR();
  let arr = ((m && m.tarif) || []).filter(t => t.aktif !== false && t.liniBisnisId === lini);
  if (q) arr = arr.filter(t => norm([t.layananNama, t.layanan, namaVendor(t.vendorId), t.lokasiId, ringkasDim(t)].join(' ')).includes(q));
  arr.sort((a, b) => (b.modal != null) - (a.modal != null) || String(a.layananNama).localeCompare(String(b.layananNama)));
  const tampil = arr.slice(0, 60);
  Q.picker = tampil;
  box.innerHTML = tampil.length ? tampil.map((t, i) => `<div class="qt-pick__item"><div class="qt-pick__nama"><b>${esc(t.layananNama || t.layanan)}</b>
      <div class="mr-sub">${esc(namaVendor(t.vendorId) || t.vendorId)} · ${esc(namaSatuanMR(t.satuanKode))}${lokasiRapi(t) ? ' · ' + esc(lokasiRapi(t)) : ''}${ringkasDim(t) ? ' · ' + esc(ringkasDim(t)) : ''}</div></div>
      <div class="qt-pick__modal">${t.modal != null ? `Modal <b>${rp(t.modal)}</b>` : '<span class="cu-st cu-st--warn">Modal kosong</span>'}</div>
      <button class="mr-btn mr-btn--kecil" data-qt="pilih-tarif" data-i="${i}">${ik('plus', 14)} Tambah</button></div>`).join('') +
    (arr.length > tampil.length ? `<p class="mr-sub" style="display:block;padding:8px 2px">Menampilkan ${tampil.length} dari ${arr.length}. Persempit pencarian untuk melihat sisanya.</p>` : '')
    : `<div class="mr-kosong" style="padding:24px 8px">${ik('cari', 24)}<p>Tidak ada tarif yang cocok. Tutup panel dan pakai “Baris bebas”.</p></div>`;
}

/* ---------- panel: setujui ---------- */
function koreksiHtml(q) {
  const ut = q.baris.filter(b => b.jenis === 'rate');
  return `<details class="qx-sub" open style="margin-top:12px"><summary><b>Koreksi harga sesuai dokumen akhir</b> <small>file Word bisa berubah setelah diunduh; ubah harga yang berbeda, atau hapus baris yang tidak jadi</small></summary>
    <div class="qt-kr">${ut.map(b => `<div class="qt-kr__r" data-kr-id="${b.id}"><span><b>${esc(b.item)}</b><small class="mr-sub"> ${esc(b.satuan)} · di sistem ${rp(b.jual)}</small></span><input data-kr="jual" inputmode="numeric" value="${esc(fmtRpIn(b.jual))}" aria-label="Harga akhir ${esc(b.item)}"><label class="qt-cek"><span><input type="checkbox" data-kr="hapus"> Tidak jadi</span></label></div>`).join('')}</div></details>`;
}
function panelSetuju(q) {
  const hi = HARI_INI();
  const hitung = bentuk => { const rc = R.rancangRate(q, bentuk); if (bentuk === 'paket') return `1 Paket Project “${q.judul}” dengan ${rc.komponen.length} komponen.`;
    const baru = rc.komponen.filter(k => S.rates.some(r => r.cid === q.customerId && r.lini === k.lini && norm(r.item) === norm(k.item) && r.satuan === k.satuan && statusRate(r) === 'aktif')).length;
    return `${rc.komponen.length} rate tunggal${baru ? `; ${baru} di antaranya menjadi versi baru dari rate aktif yang sudah ada` : ''}.`; };
  bukaPanel(`<header class="mr-panel__kepala"><div><h2>Setujui quotation</h2><p class="mr-sub">${esc(q.nomor)} · ${esc(namaCust(q))}</p></div><button class="mr-ikonbtn" data-aksi="tutup-layer" aria-label="Tutup">${ik('tutup')}</button></header>
  <div class="mr-panel__isi">
    <div class="mr-banner">${ik('info')}<div>Quotation dianggap disetujui setelah dokumen bertanda tangan customer diunggah. Rate Disetujui terbentuk otomatis, tanpa input ulang.</div></div>
    <div class="qt-grid">
      <label class="mr-f qt-c6"><span>Tanggal approve *</span><input id="qs-appr" type="date" value="${hi}" max="${hi}"></label>
      <label class="mr-f qt-c6"><span>Rate berlaku sampai <em class="cu-opsional">(kosong = tanpa batas)</em></span><input id="qs-sampai" type="date" value="${tambahBulan(hi, AQ.masaRateBulan)}"></label>
      <label class="mr-f qt-c12"><span>Dokumen penawaran bertanda tangan *</span><input id="qs-file" type="file" accept=".pdf,.png,.jpg,.jpeg"><small class="cu-hint">PDF atau gambar, maksimal 8 MB.</small></label>
    </div>
    <div class="mr-banner" style="margin-top:12px">${ik(q.tipe === 'project' ? 'file' : 'riwayat')}<div>${q.tipe === 'project' ? `<b>Harga total project</b>: dicatat sebagai <b>satu Paket Project</b> (${esc(hitung('paket'))}) Sekali jadi, tidak menggantikan rate mana pun dan tidak berlanjut.` : `<b>Harga per layanan</b>: dicatat sebagai <b>rate terpisah per baris</b> (${esc(hitung('terpisah'))}) Berlanjut sebagai Rate Disetujui; rute yang sama menjadi versi baru.`}</div></div>
    ${q.kosong ? `<div class="mr-banner mr-banner--peringatan" style="margin-top:12px">${ik('peringatan')}<div><b>Quotation manual tanpa rincian di sistem.</b> Status dan dokumen bertanda tangan dicatat, tetapi <b>Rate Disetujui tidak terbentuk otomatis</b>. Tambahkan lewat Customer → Tambah rate setelah ini.</div></div>` : (q.jalur === 'word' ? koreksiHtml(q) : '')}
    <p class="mr-galat" id="pn-galat" hidden></p>
  </div>
  <footer class="mr-panel__kaki"><button class="mr-btn" data-aksi="tutup-layer">Batal</button><button class="mr-btn mr-btn--utama" id="qs-ok" data-qt="setujui-ok" data-id="${q.id}">${ik('setuju', 16)} Setujui dan buat rate</button></footer>`);
}
async function aksiSetujuOk(btn) {
  const q = Repo.baca(btn.dataset.id); if (!q) return;
  const appr = $('#qs-appr').value, sampai = $('#qs-sampai').value, f = $('#qs-file').files[0], hi = HARI_INI();
  const bentuk = q.tipe === 'project' ? 'paket' : 'terpisah';
  const err = [];
  if (!appr) err.push('Tanggal approve wajib diisi.'); else if (appr > hi) err.push('Tanggal approve tidak boleh di masa depan.');
  if (sampai && appr && sampai < appr) err.push('“Rate berlaku sampai” tidak boleh sebelum tanggal approve.');
  if (!f) err.push('Unggah dokumen penawaran bertanda tangan. Tanpa dokumen, quotation tidak bisa disetujui.');
  if (f && f.size > 8 * 1024 * 1024) err.push('Ukuran file melebihi 8 MB.');
  if (bentuk === 'terpisah') { const seen = new Map(); R.rancangRate(q, 'terpisah').komponen.forEach((k, i) => { const key = [k.lini, norm(k.item), k.satuan].join('|'); if (seen.has(key)) err.push(`Baris ${seen.get(key) + 1} dan ${i + 1} sama (lini, item, satuan). Ubah salah satu, atau pilih Paket Project.`); else seen.set(key, i); }); }
  let koreksi = null; if ($$('[data-kr-id]').length) { koreksi = {}; $$('[data-kr-id]').forEach(r => { const id = r.dataset.krId, hapus = $('[data-kr=hapus]', r).checked, jual = angkaRp($('[data-kr=jual]', r).value); if (!hapus && !(jual > 0)) err.push('Harga akhir ' + (q.baris.find(b => b.id === id) || {}).item + ' harus lebih dari 0, atau centang “Tidak jadi”.'); koreksi[id] = { jual: hapus ? null : jual, hapus }; }); if (!err.length && Object.values(koreksi).every(k => k.hapus)) err.push('Semua baris ditandai tidak jadi. Tandai quotation Ditolak atau Tidak dipakai saja.'); }
  if (err.length) return galatPanel('<b>Belum bisa disimpan:</b><br>' + err.map(esc).join('<br>'));
  $('#pn-galat').hidden = true; const pulih = sibuk(btn, 'Menyimpan…');
  const dokData = await bacaFile(f);
  if (!dokData) { pulih(); return galatPanel('<b>File tidak bisa dibaca.</b> Coba file lain (maksimal 8 MB).'); }
  let hasil;
  try { hasil = await Repo.setujui(q.id, { appr, sampai, bentuk, dokNama: f.name, dokData, koreksi }); }
  catch (er) { pulih(); return galatPanel(`<b>GAGAL.</b> Tidak ada yang tersimpan: status quotation dan Rate Disetujui tidak berubah.<br>${esc(er.message)}`); }
  tutupPanel(); segarSemua();
  if (q.kosong) { toast(`Quotation <b>${esc(q.nomor)}</b> disetujui dan terverifikasi. <b>Tidak ada rate otomatis</b>: tambahkan lewat Customer → Tambah rate.`); return; }
  toast(`Quotation <b>${esc(q.nomor)}</b> disetujui dan terverifikasi. ${hasil.paketId ? 'Terbentuk <b>1 Paket Project</b>' : `Terbentuk <b>${hasil.rateIds.length} rate</b>${hasil.versiBaru ? ` (${hasil.versiBaru} menjadi versi baru)` : ''}`} di Rate Disetujui ${esc(namaCust(q))}.${hasil.custAktif ? ' Status customer menjadi Aktif.' : ''}`);
}

