/* angka rupiah: pemisah ribuan langsung saat mengetik (4000000 jadi 4.000.000) */
function ribuanLangsung(el) {
  const v = el.value, pos = el.selectionStart == null ? v.length : el.selectionStart, koma = v.indexOf(',');
  const intRaw = (koma >= 0 ? v.slice(0, koma) : v).replace(/\D/g, '').replace(/^0+(?=\d)/, ''), des = koma >= 0 ? v.slice(koma + 1).replace(/\D/g, '').slice(0, 2) : null;
  const f = (intRaw ? Number(intRaw).toLocaleString('id-ID') : (koma >= 0 ? '0' : '')) + (des !== null ? ',' + des : '');
  if (f === v) return; const sebelum = v.slice(0, pos).replace(/[^\d,]/g, '').length; el.value = f;
  let n = 0, p = 0; for (; p < f.length && n < sebelum; p++) if (/[\d,]/.test(f[p])) n++; try { el.setSelectionRange(p, p); } catch { }
}
