async function aksiGantiNomor(btn) {
  const q = Repo.baca(btn.dataset.id); if (!q) return;
  const baru = String(($('#gn-nomor') || {}).value || '').trim().replace(/\s+/g, ' '), alasan = String(($('#gn-alasan') || {}).value || '').trim(), tgl = q.tanggalTerbit || q.dikirim || HARI_INI();
  if (!baru) return galatPanel('Isi nomor baru.');
  if (norm(baru) === norm(q.nomor)) return galatPanel('Nomor baru sama dengan nomor sekarang.');
  if (alasan.length < 5) return galatPanel('Alasan wajib diisi (minimal 5 huruf) supaya penggantian nomor bisa ditelusuri.');
  const lain = pemakaiNomor(baru, tgl, q.id);
  if (lain.length) return galatPanel(`<b>Nomor ${esc(baru)} bentrok</b> dengan ${lain.map(esc).join(', ')}. Pilih nomor lain.`);
  if (!uraiNomor(baru, tgl) && !await konfirmasi({ judul: 'Nomor tidak sesuai pola penomoran', aksi: 'Tetap pakai', isi: `<p style="margin:0">“${esc(baru)}” tidak sesuai pola nomor di Pengaturan dokumen, jadi urutannya tidak bisa dicek otomatis dan penghitung tidak ikut naik.</p>` })) return;
  const pulih = sibuk(btn, 'Menyimpan…');
  try { await Repo.gantiNomor(q.id, baru, alasan); }
  catch (er) { pulih(); return galatPanel(`<b>GAGAL.</b> Nomor tidak berubah.<br>${esc(er.message)}`); }
  tutupPanel(); segarSemua(); toast(`Nomor diganti dari <b>${esc(q.nomor)}</b> ke <b>${esc(baru)}</b>. Unduh ulang dokumennya lalu kirim ulang ke customer.`);
}
