/* Nama file tidak boleh memuat "/", jadi nomor ditulis dengan - atau _ . Dicoba dulu sebagai pola penomoran aktif; kalau tidak cocok, pola lama (angka-huruf). */
function nomorDariNamaFile(nm) {
  const kandidat = [nm.replace(/_/g, '/'), nm.replace(/[-_]/g, '/')].map(k => k.replace(/\/M(?=\/)/gi, '-M'));  /* penanda manual "/M/" kembali menempel di jenis: QL-M */
  const cocok = kandidat.find(k => uraiNomor(k, HARI_INI()));
  return cocok || (nm.match(/\d{2,4}[\/_-][A-Z][A-Z0-9_\/-]+/i) || [nm])[0].replace(/_/g, '/');
}
