  const catatan = riwayatBaru.map(x => [x, catatanNomorUnggah(x.nomor, x.tanggalKirim)]).filter(([, c]) => c);
  if (catatan.length && !await konfirmasi({ judul: 'Periksa nomor yang diunggah', aksi: 'Tetap simpan', isi: `<p style="margin:0 0 8px">Nomor quotation berikut perlu dicek supaya penomoran sistem tetap berurutan di atas PDF yang diunggah:</p><ul style="margin:0 0 8px;padding-left:18px">${catatan.map(([x, c]) => `<li><b>${esc(x.nomor)}</b>: ${c}</li>`).join('')}</ul><p class="mr-sub" style="display:block;margin:0">Contoh nomor yang terbaca: <b>${esc(R.nomorResmi(7, HARI_INI(), seriBawaan(), true))}</b>. Pilih <b>Batal</b> untuk memperbaiki nomornya.</p>` })) return;
